import{_ as i,o as a,c as r,ao as t,at as n}from"./chunks/framework.b-LH1559.js";const f=JSON.parse('{"title":"Architecture","description":"","frontmatter":{"permalink":"/docs/getting-started/architecture/"},"headers":[],"relativePath":"docs/getting-started/architecture.md","filePath":"docs/getting-started/architecture.md"}'),s={name:"docs/getting-started/architecture.md"};function o(l,e,c,d,h,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>The architecture of the Service Lifecycle Management consists of serveral components:</p><p><img src="'+n+'" alt="architecture"></p><h2 id="discovery-server" tabindex="-1">Discovery Server <a class="header-anchor" href="#discovery-server" aria-label="Permalink to “Discovery Server”">​</a></h2><p>As Discovery Server <a href="https://www.consul.io" target="_blank" rel="noreferrer">Consul</a> from HashiCorp is used. It provides the following functionalities:</p><ul><li>List resources</li><li>List services</li></ul><h2 id="credential-manager" tabindex="-1">Credential Manager <a class="header-anchor" href="#credential-manager" aria-label="Permalink to “Credential Manager”">​</a></h2><p>As Credential Manager <a href="https://www.vaultproject.io" target="_blank" rel="noreferrer">Vault</a> from HashiCrop is used. It provides the following functionalities: Provided functionalities:</p><ul><li>Management of SSH credentials</li><li>PKI certificate authority</li><li>Docker registry credentials</li><li>Service credentials</li></ul><h2 id="configuration-manager" tabindex="-1">Configuration Manager <a class="header-anchor" href="#configuration-manager" aria-label="Permalink to “Configuration Manager”">​</a></h2><p>As Configuration manager <a href="https://github.com/ansible/awx" target="_blank" rel="noreferrer">AWX</a> from ReaHat is used. It provides the following functionalities: Provided functionalities:</p><ul><li>Setup of Deployment Capabilites</li><li>Deployment of services</li></ul><h2 id="identity-and-access-management" tabindex="-1">Identity and Access Management <a class="header-anchor" href="#identity-and-access-management" aria-label="Permalink to “Identity and Access Management”">​</a></h2><p>For Identity and Access Management <a href="https://www.keycloak.org" target="_blank" rel="noreferrer">Keycloak</a> is used. It provides the following functionalities: Provided functionalities:</p><ul><li>User Management</li><li>Access Control</li><li>Permissions and role Management</li></ul><h2 id="service-registry" tabindex="-1">Service Registry <a class="header-anchor" href="#service-registry" aria-label="Permalink to “Service Registry”">​</a></h2><p>The Service Registry is a custom implementation. It provides the following functionalities: Provided functionalities:</p><ul><li>Catalog of service offerings</li><li>Orchestration of service (un)deployments</li></ul><p>The source code is expected to be made public by the end of 2022.</p><h2 id="resource-registry" tabindex="-1">Resource Registry <a class="header-anchor" href="#resource-registry" aria-label="Permalink to “Resource Registry”">​</a></h2><p>The Resource Registry is a custom implementation. It provides the following functionalities:</p><ul><li>Management of resources</li><li>Management of Deployment Capabilites</li></ul><p>The source code is expected to be made public by the end of 2022.</p><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to “UI”">​</a></h2><p>The UI is a custom implementation. It provides the following functionalities:</p><ul><li>User interface</li><li>Web-based</li></ul><p>The source code is expected to be made public by the end of 2022.</p>',27)])])}const g=i(s,[["render",o]]);export{f as __pageData,g as default};
